from dataclasses import dataclass, field
from typing import List, Dict, Any

@dataclass
class DocumentText:
    text: str

@dataclass
class DocumentLayoutBlock:
    text: str
    bounding_boxes: List[float] # [x1, y1, x2, y2, ...]

@dataclass
class DocumentTable:
    rows: List[List[str]]
    bounding_boxes: List[float]

