import os
import boto3
from document_client import get_textract_client
from document_models import DocumentTable, DocumentExtractionResult

def extract_tables(payload, config=None):
    config = config or {}
    client = get_textract_client()

    response = client.analyze_document(
        Document={
            'Bytes': payload['document_bytes']
        },
        FeatureTypes=['TABLES']
    )

    tables = []
    text_content = ""

    blocks = response['Blocks']
    block_map = {block['Id']: block for block in blocks}

    for block in blocks:
        if block['BlockType'] == 'PAGE':
            for relationship in block.get('Relationships', []):
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        child_block = block_map[child_id]
                        if child_block['BlockType'] == 'LINE':
                            text_content += child_block['Text'] + "\n"

        if block['BlockType'] == 'TABLE':
            rows = []
            table_bounding_boxes = [
                block['Geometry']['BoundingBox']['Left'],
                block['Geometry']['BoundingBox']['Top'],
                block['Geometry']['BoundingBox']['Width'],
                block['Geometry']['BoundingBox']['Height']
            ]

            for relationship in block.get('Relationships', []):
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        cell_block = block_map[child_id]
                        if cell_block['BlockType'] == 'CELL':
                            row_index = cell_block['RowIndex']
                            col_index = cell_block['ColumnIndex']
                            cell_text = ""
                            for cell_relationship in cell_block.get('Relationships', []):
                                if cell_relationship['Type'] == 'CHILD':
                                    for word_id in cell_relationship['Ids']:
                                        word_block = block_map[word_id]
                                        if word_block['BlockType'] == 'WORD':
                                            cell_text += word_block['Text'] + " "

                            # Ensure rows list is large enough
                            while len(rows) < row_index:
                                rows.append([])
                            # Ensure current row is large enough
                            while len(rows[row_index - 1]) < col_index:
                                rows[row_index - 1].append("")

                            rows[row_index - 1][col_index - 1] = cell_text.strip()

            if rows:
                tables.append(DocumentTable(rows=rows, bounding_boxes=table_bounding_boxes))

    return DocumentExtractionResult(
        text_content=text_content,
        tables=tables
    )

import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential
from document_client import get_azure_document_intelligence_client
from document_models import DocumentKeyValue, DocumentExtractionResult
import io

def extract_key_values(payload, config=None):
    config = config or {}

    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT") or config.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    api_key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_API_KEY") or config.get("AZURE_DOCUMENT_INTELLIGENCE_API_KEY")

    if not all([endpoint, api_key]):
        raise ValueError("Missing AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT or AZURE_DOCUMENT_INTELLIGENCE_API_KEY environment variables/config.")

    client = get_azure_document_intelligence_client(endpoint, api_key)

    poller = client.begin_analyze_document(
        "prebuilt-document", # Use a prebuilt model that supports key-value pairs
        io.BytesIO(payload['document_bytes']),
        content_type=payload['mime_type']
    )
    result = poller.result()

    key_values = []
    for page in result.pages:
        for kv_pair in page.key_value_pairs:
            if kv_pair.key and kv_pair.value:
                key_values.append(DocumentKeyValue(
                    key=kv_pair.key.content,
                    value=kv_pair.value.content,
                    key_bounding_boxes=[point.x, point.y for point in kv_pair.key.bounding_regions[0].polygon] if kv_pair.key.bounding_regions else [],
                    value_bounding_boxes=[point.x, point.y for point in kv_pair.value.bounding_regions[0].polygon] if kv_pair.value.bounding_regions else []
                ))

    return DocumentExtractionResult(
        text_content=result.content,
        key_values=key_values
    )

import os
import json
from openai import OpenAI
from document_client import get_openai_client
from document_models import DocumentField

def document_field_extraction(payload, config=None):
    config = config or {}

    openai_api_key = os.environ.get("OPENAI_API_KEY") or config.get("OPENAI_API_KEY")
    if not openai_api_key:
        raise ValueError("Missing OPENAI_API_KEY environment variable/config.")

    client = get_openai_client(openai_api_key)

    # The fields to extract should be provided in the config or payload
    # For this example, let's assume a generic extraction of 'name' and 'address'
    # In a real scenario, the prompt would be dynamically generated based on required fields.
    fields_to_extract = config.get("FIELDS_TO_EXTRACT", ["name", "address", "invoice_total"])

    prompt_messages = [
        {
            "role": "system", 
            "content": "You are an expert at extracting structured information from text. Extract the following fields from the provided document text as a JSON object: " + ", ".join(fields_to_extract) + ". If a field is not found, use an empty string. Output only the JSON object."
        },
        {
            "role": "user", 
            "content": f"Document Text: {payload['text']}"
        }
    ]

    response = client.chat.completions.create(
        model="gpt-4o-mini", # Using gpt-4o-mini as a cost-effective alternative for demonstration
        messages=prompt_messages,
        response_format={ "type": "json_object" }
    )

    extracted_data = json.loads(response.choices[0].message.content)

    document_fields = []
    for field_name, field_value in extracted_data.items():
        document_fields.append(DocumentField(field_name=field_name, field_value=str(field_value)))

    return document_fields
